command:
$ErrorActionPreference="Stop"
$root=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $root
& git fetch origin main work/search-v3-indexed-filename-20261008 --no-tags
if($LASTEXITCODE -ne 0){throw "fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne "387efa622f6a9ce6685e3bffb98299df0503de3c"){throw "main moved"}
try {
 & git switch --detach ffc2466be51c32c1cf7454a2df80fe4f8c3f5f99
 if($LASTEXITCODE -ne 0){throw "checkout failed"}
 $src=Get-Content "tests\winui\test_indexed_search_gui.py" -Raw -Encoding UTF8
 $old='    env["FLY_CONTENT_REGEX_VISUAL_CAPTURE_PATH"]=str(shot)'
 $new='    env["FLY_CONTENT_REGEX_VISUAL_CAPTURE_PATH"]=str(base/("startup-"+args.capture+".bmp"))'+"`n"+'    env["FLY_NETWORK_VISUAL_CAPTURE_PATH"]=str(shot)'
 $anchor='        wait(ready,"indexed search window",24)'
 $fixed=$anchor+"`n"+'        assert ctypes.windll.user32.SetWindowPos(window.handle,0,0,0,972,720,0x0016),"fixed window resize failed"'
 if(-not $src.Contains($old) -or -not $src.Contains($anchor)){throw "visual anchors missing"}
 $src=$src.Replace($old,$new).Replace($anchor,$fixed)
 $src=$src.Replace('str(Path(__file__).with_name("test_indexed_search_native.py"))','str(ROOT/"tests"/"winui"/"test_indexed_search_native.py")')
 $script=Join-Path $root "logs\search-v3-indexed\visual-fixed-after.py"
 [IO.File]::WriteAllText($script,$src,(New-Object Text.UTF8Encoding($false)))
 $env:PYTHONPATH=Join-Path $root "tests\winui"
 & python -X utf8 $script --capture after --configuration Release
 if($LASTEXITCODE -ne 0){throw "fixed AFTER visual capture failed"}
 Write-Host "SEARCH_V3_FIXED_AFTER=PASS"
} finally {
 Remove-Item -LiteralPath (Join-Path $root "logs\search-v3-indexed\visual-fixed-after.py") -Force -ErrorAction SilentlyContinue
 & git switch main
 if($LASTEXITCODE -ne 0){throw "main restore failed"}
}
